CREATE TABLE collection_checkpoint_pages (job_id TEXT NOT NULL REFERENCES collection_checkpoints(job_id) ON DELETE CASCADE, employee_code TEXT NOT NULL, data TEXT NOT NULL, PRIMARY KEY(job_id,employee_code));
CREATE TABLE collection_checkpoints (job_id TEXT PRIMARY KEY, connection_revision INTEGER NOT NULL, fingerprint TEXT NOT NULL, created_at INTEGER NOT NULL, token TEXT NOT NULL UNIQUE);
CREATE TABLE collection_live_items (job_id TEXT NOT NULL REFERENCES collection_live_runs(job_id) ON DELETE CASCADE, item_key TEXT NOT NULL, date TEXT NOT NULL, data TEXT NOT NULL, PRIMARY KEY(job_id,date,item_key));
CREATE TABLE collection_live_runs (job_id TEXT PRIMARY KEY, owner TEXT NOT NULL, metadata TEXT NOT NULL);
CREATE TABLE connections (provider TEXT PRIMARY KEY CHECK(provider='paycom'), enabled INTEGER NOT NULL DEFAULT 0 CHECK(enabled IN (0,1)), status TEXT NOT NULL DEFAULT 'not_connected', error TEXT, account_label TEXT, updated_at TEXT NOT NULL, verified_at TEXT, revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE employee_timecard_syncs ( employee_code TEXT NOT NULL, period_from TEXT NOT NULL, period_to TEXT NOT NULL, collected_at TEXT NOT NULL, data TEXT NOT NULL, PRIMARY KEY(employee_code, period_from, period_to) );
CREATE TABLE employees (publication_id TEXT NOT NULL REFERENCES publications(id) ON DELETE CASCADE, code TEXT NOT NULL, name TEXT NOT NULL, department TEXT NOT NULL, position TEXT NOT NULL, station TEXT NOT NULL, active INTEGER NOT NULL, PRIMARY KEY(publication_id,code));
CREATE TABLE owner_migrations (owner TEXT NOT NULL, id INTEGER NOT NULL, name TEXT NOT NULL, applied_at INTEGER NOT NULL, PRIMARY KEY(owner, id));
CREATE TABLE paycom_employee_sync_payload_refs ( employee_code TEXT NOT NULL, period_from TEXT NOT NULL, period_to TEXT NOT NULL, format TEXT NOT NULL DEFAULT 'paycom.employee-capture.v1' CHECK(format='paycom.employee-capture.v1'), digest TEXT NOT NULL, payload_collected_at TEXT NOT NULL, PRIMARY KEY(employee_code,period_from,period_to), FOREIGN KEY(employee_code,period_from,period_to) REFERENCES employee_timecard_syncs(employee_code,period_from,period_to) ON UPDATE CASCADE ON DELETE CASCADE, FOREIGN KEY(format,digest) REFERENCES paycom_payloads(format,digest) ON DELETE RESTRICT ) WITHOUT ROWID;
CREATE TABLE paycom_payloads ( format TEXT NOT NULL CHECK(length(format) BETWEEN 1 AND 80), digest TEXT NOT NULL CHECK(length(digest)=64 AND digest NOT GLOB '*[^0-9a-f]*'), body TEXT NOT NULL CHECK(json_valid(body)), PRIMARY KEY(format,digest), CHECK(format<>'paycom.punches.v1' OR json_type(body)='array'), CHECK(format<>'paycom.employee-capture.v1' OR json_type(body)='object') ) WITHOUT ROWID;
CREATE TABLE paycom_people ( code TEXT PRIMARY KEY, name TEXT NOT NULL, department TEXT, position TEXT, first_seen TEXT, last_seen TEXT, listed INTEGER NOT NULL CHECK(listed IN (0,1)) );
CREATE TABLE paycom_people_collected_days (date TEXT PRIMARY KEY);
CREATE TABLE paycom_people_state ( id INTEGER PRIMARY KEY CHECK(id=1), dirty INTEGER NOT NULL CHECK(dirty IN (0,1)) );
CREATE TABLE paycom_people_workdays ( employee_code TEXT NOT NULL, date TEXT NOT NULL, PRIMARY KEY(employee_code,date) );
CREATE TABLE paycom_timecard_payload_refs ( publication_id TEXT NOT NULL, employee_code TEXT NOT NULL, date TEXT NOT NULL, format TEXT NOT NULL DEFAULT 'paycom.punches.v1' CHECK(format='paycom.punches.v1'), digest TEXT NOT NULL, PRIMARY KEY(publication_id,employee_code,date), FOREIGN KEY(publication_id,employee_code,date) REFERENCES timecards(publication_id,employee_code,date) ON UPDATE CASCADE ON DELETE CASCADE, FOREIGN KEY(format,digest) REFERENCES paycom_payloads(format,digest) ON DELETE RESTRICT ) WITHOUT ROWID;
CREATE TABLE publications (id TEXT PRIMARY KEY, collected_at TEXT NOT NULL, period_from TEXT NOT NULL, period_to TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 0 CHECK(active IN (0,1)));
CREATE TABLE schedules (provider TEXT PRIMARY KEY CHECK(provider='paycom'), enabled INTEGER NOT NULL DEFAULT 0 CHECK(enabled IN (0,1)), local_time TEXT NOT NULL DEFAULT '06:00', timezone TEXT NOT NULL, next_run TEXT);
CREATE TABLE schema_migrations (id INTEGER PRIMARY KEY, name TEXT NOT NULL, applied_at INTEGER NOT NULL);
CREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE storage_identity (dsp_id TEXT NOT NULL, provider TEXT NOT NULL, source TEXT NOT NULL);
CREATE TABLE timecard_sources (publication_id TEXT NOT NULL, employee_code TEXT NOT NULL, period_key TEXT NOT NULL, url TEXT NOT NULL, PRIMARY KEY(publication_id,employee_code), FOREIGN KEY(publication_id,employee_code) REFERENCES employees(publication_id,code) ON DELETE CASCADE);
CREATE TABLE timecards (publication_id TEXT NOT NULL REFERENCES publications(id) ON DELETE CASCADE, employee_code TEXT NOT NULL, date TEXT NOT NULL, hours REAL NOT NULL, status TEXT NOT NULL, punches TEXT NOT NULL, PRIMARY KEY(publication_id,employee_code,date), FOREIGN KEY(publication_id,employee_code) REFERENCES employees(publication_id,code) ON DELETE CASCADE);
CREATE UNIQUE INDEX active_publication ON publications(active) WHERE active=1;
CREATE INDEX employees_by_code ON employees(code, publication_id);
CREATE INDEX paycom_employee_sync_payload_refs_by_digest ON paycom_employee_sync_payload_refs(format,digest);
CREATE INDEX paycom_timecard_payload_refs_by_digest ON paycom_timecard_payload_refs(format,digest);
CREATE INDEX publications_by_collection ON publications(collected_at DESC);
CREATE INDEX timecards_by_day ON timecards(publication_id,date,employee_code);
CREATE TRIGGER paycom_payload_syncs_delete AFTER DELETE ON employee_timecard_syncs BEGIN DELETE FROM paycom_employee_sync_payload_refs WHERE employee_code=OLD.employee_code AND period_from=OLD.period_from AND period_to=OLD.period_to; END;
CREATE TRIGGER paycom_payload_syncs_insert AFTER INSERT ON employee_timecard_syncs BEGIN DELETE FROM paycom_employee_sync_payload_refs WHERE employee_code=NEW.employee_code AND period_from=NEW.period_from AND period_to=NEW.period_to; END;
CREATE TRIGGER paycom_payload_syncs_update AFTER UPDATE ON employee_timecard_syncs BEGIN DELETE FROM paycom_employee_sync_payload_refs WHERE (employee_code=OLD.employee_code AND period_from=OLD.period_from AND period_to=OLD.period_to) OR (employee_code=NEW.employee_code AND period_from=NEW.period_from AND period_to=NEW.period_to); END;
CREATE TRIGGER paycom_payload_timecards_delete AFTER DELETE ON timecards BEGIN DELETE FROM paycom_timecard_payload_refs WHERE publication_id=OLD.publication_id AND employee_code=OLD.employee_code AND date=OLD.date; END;
CREATE TRIGGER paycom_payload_timecards_insert AFTER INSERT ON timecards BEGIN DELETE FROM paycom_timecard_payload_refs WHERE publication_id=NEW.publication_id AND employee_code=NEW.employee_code AND date=NEW.date; END;
CREATE TRIGGER paycom_payload_timecards_update AFTER UPDATE OF publication_id,employee_code,date,punches ON timecards BEGIN DELETE FROM paycom_timecard_payload_refs WHERE (publication_id=OLD.publication_id AND employee_code=OLD.employee_code AND date=OLD.date) OR (publication_id=NEW.publication_id AND employee_code=NEW.employee_code AND date=NEW.date); END;
CREATE TRIGGER paycom_payloads_immutable BEFORE UPDATE ON paycom_payloads BEGIN SELECT RAISE(ABORT,'immutable_paycom_payload'); END;
CREATE TRIGGER paycom_people_employees_delete AFTER DELETE ON employees WHEN (SELECT dirty FROM paycom_people_state WHERE id=1)=0 BEGIN UPDATE paycom_people_state SET dirty=1 WHERE id=1; END;
CREATE TRIGGER paycom_people_employees_insert AFTER INSERT ON employees WHEN (SELECT dirty FROM paycom_people_state WHERE id=1)=0 BEGIN UPDATE paycom_people_state SET dirty=1 WHERE id=1; END;
CREATE TRIGGER paycom_people_employees_update AFTER UPDATE ON employees WHEN (SELECT dirty FROM paycom_people_state WHERE id=1)=0 BEGIN UPDATE paycom_people_state SET dirty=1 WHERE id=1; END;
CREATE TRIGGER paycom_people_publications_delete AFTER DELETE ON publications WHEN (SELECT dirty FROM paycom_people_state WHERE id=1)=0 BEGIN UPDATE paycom_people_state SET dirty=1 WHERE id=1; END;
CREATE TRIGGER paycom_people_publications_insert AFTER INSERT ON publications WHEN (SELECT dirty FROM paycom_people_state WHERE id=1)=0 BEGIN UPDATE paycom_people_state SET dirty=1 WHERE id=1; END;
CREATE TRIGGER paycom_people_publications_update AFTER UPDATE ON publications WHEN (SELECT dirty FROM paycom_people_state WHERE id=1)=0 BEGIN UPDATE paycom_people_state SET dirty=1 WHERE id=1; END;
CREATE TRIGGER paycom_people_timecards_delete AFTER DELETE ON timecards WHEN (SELECT dirty FROM paycom_people_state WHERE id=1)=0 BEGIN UPDATE paycom_people_state SET dirty=1 WHERE id=1; END;
CREATE TRIGGER paycom_people_timecards_insert AFTER INSERT ON timecards WHEN (SELECT dirty FROM paycom_people_state WHERE id=1)=0 BEGIN UPDATE paycom_people_state SET dirty=1 WHERE id=1; END;
CREATE TRIGGER paycom_people_timecards_update AFTER UPDATE ON timecards WHEN (SELECT dirty FROM paycom_people_state WHERE id=1)=0 BEGIN UPDATE paycom_people_state SET dirty=1 WHERE id=1; END;
